/* DPCT_ORIG template<class T>
__inline__ __device__
void NFFT_H_output(unsigned int number_of_batches, T* __restrict__ image,
               unsigned int warp_size_power, unsigned int number_of_domains,
               unsigned int globalThreadId, unsigned int sharedMemFirstCellIdx)*/
template <class T>
__inline__ void NFFT_H_output(unsigned int number_of_batches, T* __restrict__ image, unsigned int warp_size_power,
                              unsigned int number_of_domains, unsigned int globalThreadId,
                              unsigned int sharedMemFirstCellIdx, char* _shared_mem)
{
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    realType_t<T>* shared_mem = (realType_t<T>*)_shared_mem;

    for (unsigned int batch = 0; batch < number_of_batches; batch++)
    {
        T cell_coefficient;
        if constexpr (is_complex_type_v<T>)
        {
            cell_coefficient._real =
                shared_mem[sharedMemFirstCellIdx + (batch << warp_size_power)];
            cell_coefficient._imag =
                /* DPCT_ORIG                 shared_mem[sharedMemFirstCellIdx + (batch << warp_size_power) +
                   warpSize];*/
                shared_mem[sharedMemFirstCellIdx + (batch << warp_size_power) +
                           sycl::ext::oneapi::this_work_item::get_sub_group().get_local_range().get(0)];
        }
        else
        {
            cell_coefficient = shared_mem[sharedMemFirstCellIdx + (batch << warp_size_power)];
        }
/* DPCT_ORIG         image[(batch*gridDim.y+blockIdx.y) * number_of_domains + globalThreadId] =*/
        image[(batch * item_ct1.get_group_range(1) + item_ct1.get_group(1)) * number_of_domains + globalThreadId] =
            cell_coefficient;
    }
}

/* DPCT_ORIG template<class T, unsigned int D, template<class, unsigned int> class K>
__inline__ __device__
void NFFT_H_convolve(
    unsigned int number_of_samples, unsigned int number_of_batches,
    unsigned int number_of_domains,
    const vector_td<realType_t<T>,D> * __restrict__ traj_positions, const  T* __restrict__ samples, const unsigned int *
__restrict__ tuples_last, const unsigned int * __restrict__ bucket_begin, const unsigned int * __restrict__ bucket_end,
    unsigned int warp_size_power,
    unsigned int globalThreadId, vector_td<unsigned int,D> domainPos,
    unsigned int sharedMemFirstCellIdx,
    const ConvolutionKernel<realType_t<T>, D, K>* kernel)*/
template <class T, unsigned int D, template <class, unsigned int> class K>
/*
DPCT1110:6: The total declared local variable size in device function NFFT_H_convolve exceeds 128 bytes and may cause
high register pressure. Consult with your hardware vendor to find the total register size available and adjust the code,
or use smaller sub-group size to avoid high register pressure.
*/
__inline__ void
NFFT_H_convolve(unsigned int number_of_samples, unsigned int number_of_batches, unsigned int number_of_domains,
                const vector_td<realType_t<T>, D>* __restrict__ traj_positions, const T* __restrict__ samples,
                const unsigned int* __restrict__ tuples_last, const unsigned int* __restrict__ bucket_begin,
                const unsigned int* __restrict__ bucket_end, unsigned int warp_size_power, unsigned int globalThreadId,
                vector_td<unsigned int, D> domainPos, unsigned int sharedMemFirstCellIdx,
                const ConvolutionKernel<realType_t<T>, D, K>* kernel, char* _shared_mem)
{
    using namespace thrust::cuda_cub;

    realType_t<T> *shared_mem = (realType_t<T>*) _shared_mem;

    // Cell position as reald
    vector_td<realType_t<T>,D> cell_pos = vector_td<realType_t<T>,D>( domainPos );
    
    // Convolve samples onto the domain (shared memory)
/* DPCT_ORIG     const unsigned int frame_offset = blockIdx.y*number_of_domains;*/
    const unsigned int frame_offset =
        sycl::ext::oneapi::this_work_item::get_nd_item<3>().get_group(1) * number_of_domains;
    for (unsigned int i = bucket_begin[globalThreadId + frame_offset];
         i < bucket_end[globalThreadId + frame_offset];
         i++)
    {
        // Safety precaution. TODO
        unsigned int sampleIdx = tuples_last[i];

        // Safety precaution. TODO
        vector_td<realType_t<T>,D> sample_pos = traj_positions[sampleIdx];
        
        // Calculate the distance between the cell and the sample.
        vector_td<realType_t<T>, D> delta = abs(sample_pos-cell_pos);
        
        // Compute convolution weights.
        float weight = kernel->get(delta);      

        // Safety measure.
/* DPCT_ORIG         if (!isfinite(weight))*/
        if (!sycl::isfinite(weight))
            continue;
        
        // Apply filter to input images.
        for (int batch = 0; batch < number_of_batches; batch++)
        {
            unsigned int idx = sampleIdx * number_of_batches + batch;
      
            // Apply filter to shared memory domain.
/* DPCT_ORIG             T sample_val  = cub::ThreadLoad<cub::LOAD_CS>(samples + idx);*/
            T sample_val = *(samples + idx);

            if constexpr (is_complex_type_v<T>)
            {
                shared_mem[sharedMemFirstCellIdx + (batch << warp_size_power)] +=
                    (weight * sample_val._real);
/* DPCT_ORIG                 shared_mem[sharedMemFirstCellIdx + (batch << warp_size_power) + warpSize] +=*/
                shared_mem[sharedMemFirstCellIdx + (batch << warp_size_power) +
                           sycl::ext::oneapi::this_work_item::get_sub_group().get_local_range().get(0)] +=
                    (weight * sample_val._imag);
            }
            else
            {
                shared_mem[sharedMemFirstCellIdx + (batch << warp_size_power)] +=
                    (weight * sample_val);
            }
        }
    }
}

