namespace Gadgetron
{

    template<template<class> class ARRAY, class REAL, unsigned int D>
    NFFT_plan<ARRAY, REAL, D>::NFFT_plan(
        const vector_td <size_t, D> &matrix_size,
        const vector_td <size_t, D> &matrix_size_os,
        REAL width)
      : matrix_size_(matrix_size)
      , matrix_size_os_(matrix_size_os)
      , width_(width)
    {
        KaiserKernel<REAL, D> kernel(vector_td<unsigned int, D>(matrix_size),
                                     vector_td<unsigned int, D>(matrix_size_os),
                                     width);
        conv_ = GriddingConvolution<ARRAY, complext<REAL>, D, KaiserKernel>::make(
            matrix_size, matrix_size_os, kernel);
    }


    template<template<class> class ARRAY, class REAL, unsigned int D>
    NFFT_plan<ARRAY, REAL, D>::NFFT_plan(
        const vector_td <size_t, D>& matrix_size,
        REAL os_factor,
        REAL width)
      : matrix_size_(matrix_size)
      , matrix_size_os_(vector_td<size_t, D>(os_factor * vector_td<REAL, D>(matrix_size)))
      , width_(width)
    {
        KaiserKernel<REAL, D> kernel(vector_td<unsigned int, D>(matrix_size),
                                     os_factor,
                                     width);
        conv_ = GriddingConvolution<ARRAY, complext<REAL>, D, KaiserKernel>::make(
            matrix_size, os_factor, kernel);
    }


    template<template<class> class ARRAY, class REAL, unsigned int D>
    void NFFT_plan<ARRAY, REAL, D>::preprocess(
        const ARRAY<vector_td<REAL,D>>& trajectory,
        NFFT_prep_mode mode)
    {
        // Choose preparation mode.
        GriddingConvolutionPrepMode prep_mode;
        switch (mode)
        {
            case NFFT_prep_mode::C2NC:
                prep_mode = GriddingConvolutionPrepMode::C2NC;
                break;
            case NFFT_prep_mode::NC2C:
                prep_mode = GriddingConvolutionPrepMode::NC2C;
                break;
            case NFFT_prep_mode::ALL:
                prep_mode = GriddingConvolutionPrepMode::ALL;
                break;
        }

        // Gridding convolution preprocessing.
        this->conv_->preprocess(trajectory, prep_mode);
    }


    template<template<class> class ARRAY, class REAL, unsigned int D>
    void NFFT_plan<ARRAY, REAL, D>::convolve(
        const ARRAY<complext<REAL>>& in,
        ARRAY<complext<REAL>>& out,
        NFFT_conv_mode mode,
        bool accumulate)
    {
        // Choose convolution mode.
        GriddingConvolutionMode conv_mode;
        switch (mode)
        {
            case NFFT_conv_mode::C2NC:
                conv_mode = GriddingConvolutionMode::C2NC;
                break;
            case NFFT_conv_mode::NC2C:
                conv_mode = GriddingConvolutionMode::NC2C;
                break;
        }

        // Run gridding convolution.
        this->conv_->compute(in, out, conv_mode, accumulate);
    }
    

    template<template<class> class ARRAY, class REAL, unsigned int D>
    void NFFT_plan<ARRAY, REAL, D>::mult_MH_M(
        const ARRAY<complext<REAL>>& in,
        ARRAY<complext<REAL>>& out,
        const ARRAY<REAL>* dcw)
    {
        size_t num_batches = in.get_number_of_elements() / (prod(this->matrix_size_) * this->conv_->get_num_frames());
        ARRAY<complext<REAL>> tmp(this->conv_->get_num_samples(),
                                  this->conv_->get_num_frames(),
                                  num_batches);
        compute(in, tmp, dcw, NFFT_comp_mode::FORWARDS_C2NC);
        compute(tmp, out, dcw, NFFT_comp_mode::BACKWARDS_NC2C);
    }


    template<template<class> class ARRAY, class REAL, unsigned int D>
    void NFFT_plan<ARRAY,REAL,D>::compute(const ARRAY<complext<REAL>>& in, ARRAY<complext<REAL>>&out,
        const ARRAY<REAL> *dcw, NFFT_comp_mode mode)
    {

        typename uint64d<D>::Type image_dims = from_std_vector<size_t, D>
                ((mode == NFFT_comp_mode::FORWARDS_C2NC || mode == NFFT_comp_mode::BACKWARDS_C2NC) ? in.get_dimensions()
                                                                                                : out.get_dimensions());
        bool oversampled_image = (image_dims == this->matrix_size_os_);

        auto vec_dims = to_std_vector(this->matrix_size_os_);
        {
            const auto image = ((mode == NFFT_comp_mode::FORWARDS_C2NC ||
                                mode == NFFT_comp_mode::BACKWARDS_C2NC) ? &in : &out);
            for (unsigned int d = D; d<image->get_number_of_dimensions(); d++)
                vec_dims.push_back(image->get_size(d));
        }

        switch (mode)
        {

            case NFFT_comp_mode::FORWARDS_C2NC: {
                if (!oversampled_image) {
                    auto working_image = ARRAY<complext<REAL >> (vec_dims);
                    pad<complext<REAL >,D> (in, working_image);
                    compute_NFFT_C2NC(working_image, out);
                } else {
                    auto copy = in;
                    compute_NFFT_C2NC(copy, out);
                }

                if (dcw) {
                    out *= *dcw;
                }

            }
                break;

            case NFFT_comp_mode::FORWARDS_NC2C: {

                // Density compensation
                auto working_samples = in;
                boost::shared_ptr<ARRAY<complext<REAL >> > samples_dcw;
                if (dcw) {
                    working_samples *= *dcw;
                }


                if (!oversampled_image) {
                    auto working_image = ARRAY<complext<REAL >> (vec_dims);
                    compute_NFFT_NC2C(working_samples, working_image);
                    crop<complext<REAL > , D >
                                            ((this->matrix_size_os_ - this->matrix_size_) >> 1,this->matrix_size_, working_image, out);
                } else {
                    compute_NFFT_NC2C(working_samples, out);
                }
            }
                break;

            case NFFT_comp_mode::BACKWARDS_NC2C: {

                // Density compensation
                const ARRAY<complext<REAL>> *working_samples = &in;
                boost::shared_ptr<ARRAY<complext<REAL >> > samples_dcw;
                if (dcw) {
                    samples_dcw = boost::make_shared<ARRAY<complext<REAL >> > (in);
                    *samples_dcw *= *dcw;
                    working_samples = samples_dcw.get();
                }


                if (!oversampled_image) {
                    auto working_image = ARRAY<complext<REAL>>(vec_dims);
                    compute_NFFTH_NC2C(*working_samples, working_image);
                    crop<complext<REAL >,D>((this->matrix_size_os_ - this->matrix_size_) >> 1,this->matrix_size_, working_image, out);
                } else {
                    compute_NFFTH_NC2C(*working_samples, out);
                }

            }
                break;

            case NFFT_comp_mode::BACKWARDS_C2NC: {

                if (!oversampled_image) {
                    auto working_image = ARRAY<complext<REAL >> (vec_dims);
                    pad<complext<REAL >,D>(in, working_image);
                    compute_NFFTH_C2NC(working_image, out);
                } else {
                    auto copy = in;
                    compute_NFFTH_C2NC(copy, out);
                }

                if (dcw)
                    out *= *dcw;
            }
                break;
        };
    }


    template<template<class> class ARRAY, class REAL, unsigned int D>
    void NFFT_plan<ARRAY, REAL, D>::compute_NFFT_C2NC(ARRAY<complext<REAL>>& image, ARRAY<complext<REAL>>& samples) {

        deapodize(image);
        fft(image, NFFT_fft_mode::FORWARDS);
        convolve(image, samples,  NFFT_conv_mode::C2NC);
    }


    template<template<class> class ARRAY, class REAL, unsigned int D>
    void NFFT_plan<ARRAY, REAL, D>::compute_NFFT_NC2C(const ARRAY<complext<REAL>>& samples, ARRAY<complext<REAL>>& image) {

        convolve(samples, image, NFFT_conv_mode::NC2C);
        fft(image, NFFT_fft_mode::FORWARDS);
        deapodize(image, true);
    }


    template<template<class> class ARRAY, class REAL, unsigned int D>
    void NFFT_plan<ARRAY, REAL, D>::compute_NFFTH_NC2C(const ARRAY<complext<REAL>>& samples, ARRAY<complext<REAL>>& image) {

        convolve(samples, image,  NFFT_conv_mode::NC2C);
        fft(image, NFFT_fft_mode::BACKWARDS);
        deapodize(image);
    }


    template<template<class> class ARRAY, class REAL, unsigned int D>
    void NFFT_plan<ARRAY, REAL, D>::compute_NFFTH_C2NC(ARRAY<complext<REAL>>& image, ARRAY<complext<REAL>>& samples) {

        deapodize(image, true);
        convolve(samples, image, NFFT_conv_mode::NC2C);
        fft(image, NFFT_fft_mode::BACKWARDS);
    }

} // namespace Gadgetron
// ===== End: toolboxes/nfft/NFFT.hpp =====



using namespace Gadgetron;


template<class REAL, unsigned int D, ConvolutionType CONV>
Gadgetron::cuNFFT_impl<REAL, D, CONV>::cuNFFT_impl(
    const vector_td<size_t, D>& matrix_size,
    const vector_td<size_t, D>& matrix_size_os,
    REAL W,
    int device)
  : NFFT_plan<cuNDArray, REAL, D>(matrix_size, matrix_size_os, W)
{
    // Initialize gridding convolution. This was done in base class already, but
    // we need to do it again in order to provide the appropriate convolution
    // type.
    KaiserKernel<REAL, D> kernel(vector_td<unsigned int, D>(matrix_size),
                                 vector_td<unsigned int, D>(matrix_size_os),
                                 W);
    this->conv_ = GriddingConvolution<cuNDArray, complext<REAL>, D, KaiserKernel>::make(
        matrix_size, matrix_size_os, kernel, CONV);

    // Minimal initialization.
    this->initialize(device);
}


template<class REAL, unsigned int D, ConvolutionType CONV>
Gadgetron::cuNFFT_impl<REAL, D, CONV>::~cuNFFT_impl()
{

}


template<class REAL, unsigned int D, ConvolutionType CONV>
void
Gadgetron::cuNFFT_impl<REAL, D, CONV>::fft(cuNDArray <complext<REAL>>& data, NFFT_fft_mode mode, bool do_scale) {

    typename uint64d<D>::Type _dims_to_transform = counting_vec<size_t, D>();
    std::vector<size_t> dims_to_transform = to_std_vector(_dims_to_transform);

    if (mode == NFFT_fft_mode::FORWARDS) {
        cuNDFFT<REAL>::instance()->fft(&data, &dims_to_transform, do_scale);
    } else {
        cuNDFFT<REAL>::instance()->ifft(&data, &dims_to_transform, do_scale);
    }

}


template<class REAL, unsigned int D, ConvolutionType CONV>
void
Gadgetron::cuNFFT_impl<REAL, D, CONV>::deapodize(cuNDArray <complext<REAL>>& image, bool fourier_domain) {

    typename uint64d<D>::Type image_dims = from_std_vector<size_t, D>(image.get_dimensions());
    bool oversampled_image = (image_dims == this->matrix_size_os_);

    if (!oversampled_image) {
        throw std::runtime_error("Error: cuNFFT_impl::deapodize: ERROR: oversampled image not provided as input.");
    }
    if (fourier_domain) {
        if (!deapodization_filterFFT)
            deapodization_filterFFT = compute_deapodization_filter(true);
        image *= *deapodization_filterFFT;
    } else {
        if (!deapodization_filter)
            deapodization_filter = compute_deapodization_filter(false);
        image *= *deapodization_filter;
    }
}

template <class REAL, unsigned int D, ConvolutionType CONV>
void Gadgetron::cuNFFT_impl<REAL, D, CONV>::initialize(int device) try {
    // Device checks.
/* DPCT_ORIG     if (cudaGetDevice(&this->device_) != cudaSuccess)*/
    if (DPCT_CHECK_ERROR(this->device_ = dpct::get_current_device_id()) != 0)
    {
        throw cuda_error("Error: cuNFFT_impl::barebones:: unable to get this->device_ no");
    }
    
    if (device < 0)
    {
/* DPCT_ORIG         if (cudaGetDevice(&this->device_) != cudaSuccess)*/
        if (DPCT_CHECK_ERROR(this->device_ = dpct::get_current_device_id()) != 0)
        {
            throw cuda_error("Error: cuNFFT_impl::setup: unable to determine "
                             "device properties.");
        }
    }
    else
    {
        this->device_ = device;
    }

    int device_no_old;
/* DPCT_ORIG     if (cudaGetDevice(&device_no_old) != cudaSuccess)*/
    if (DPCT_CHECK_ERROR(device_no_old = dpct::get_current_device_id()) != 0)
        throw cuda_error("Error: cuNFFT_impl::setup: unable to get device number");

    if (this->device_ != device_no_old &&
        /* DPCT_ORIG         cudaSetDevice(this->device_) != cudaSuccess)*/
        /*
        DPCT1093:108: The "this->device_" device may be not the one intended for use. Adjust the selected device if
        needed.
        */
        DPCT_CHECK_ERROR(dpct::select_device(this->device_)) != 0)
        throw cuda_error("Error: cuNFFT_impl::setup: unable to set device");

    if (this->device_ != device_no_old &&
        /* DPCT_ORIG         cudaSetDevice(device_no_old) != cudaSuccess)*/
        /*
        DPCT1093:109: The "device_no_old" device may be not the one intended for use. Adjust the selected device if
        needed.
        */
        DPCT_CHECK_ERROR(dpct::select_device(device_no_old)) != 0)
        throw cuda_error("Error: cuNFFT_impl::setup: unable to restore device");
}
catch (sycl::exception const& exc) {
  std::cerr << exc.what() << "Exception caught at file:" << __FILE__ << ", line:" << __LINE__ << std::endl;
  std::exit(1);
}

//
// Grid fictitious trajectory with a single sample at the origin
//

/* DPCT_ORIG template<class REAL, unsigned int D, template<class, unsigned int> class K>
__global__ void
compute_deapodization_filter_kernel(typename uintd<D>::Type matrix_size_os,
                                    typename reald<REAL, D>::Type matrix_size_os_real,
                                    complext <REAL> *__restrict__ image_os,
                                    const ConvolutionKernel<REAL, D, K>* kernel)*/
template <class REAL, unsigned int D, template <class, unsigned int> class K>
void compute_deapodization_filter_kernel(typename uintd<D>::Type matrix_size_os,
                                         typename reald<REAL, D>::Type matrix_size_os_real,
                                         complext<REAL>* __restrict__ image_os,
                                         const ConvolutionKernel<REAL, D, K>* kernel)
{
/* DPCT_ORIG     const unsigned int idx = blockIdx.x * blockDim.x + threadIdx.x;*/
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    const unsigned int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) + item_ct1.get_local_id(2);
    const unsigned int num_elements = prod(matrix_size_os);

    if (idx < num_elements) {

        // Compute weight from Kaiser-Bessel filter
        const typename uintd<D>::Type cell_pos = idx_to_co(idx, matrix_size_os);

        // Sample position ("origin")
        const vector_td<REAL, D> sample_pos = REAL(0.5) * matrix_size_os_real;

        // Calculate the distance between the cell and the sample
        vector_td<REAL, D>
        cell_pos_real = vector_td<REAL, D>(cell_pos);
        const typename reald<REAL, D>::Type delta = abs(sample_pos - cell_pos_real);

        // Compute convolution weight.
        REAL weight = kernel->get(delta);

        // Output weight
        image_os[idx] = complext<REAL>(weight, 0.0f);
    }
}

