        CUBLAS_CALL(cublas_asum(handle,
                                (ii == num_splits - 1) ? remainder : batchSize, // n number of elements
                                x->get_data_ptr() + batchSize * ii, 1, &interim_result));


        if (ii == 0)
            result = interim_result;
        else
            result += interim_result;
